namespace {

// Compatibility taxonomy: status / perf / channel / release-stage all share
// the same "code → label / color / rank" lookup shape, so a single struct +
// generic FindByCode() drive every accessor below. `hex_color == 0` means
// render with [XeniaTheme textMuted]; `rank` is only meaningful for
// statuses (higher = "more playable").
struct CompatTaxonomyEntry {
  NSString* code;
  NSString* label;
  uint32_t hex_color;
  NSInteger rank;
};

const CompatTaxonomyEntry kCompatStatuses[] = {
    {@"playable", @"Playable", 0x34d399, 4}, {@"ingame", @"In-Game", 0x60a5fa, 3},
    {@"intro", @"Intro", 0xfbbf24, 2},       {@"loads", @"Loads", 0xfb923c, 1},
    {@"nothing", @"Nothing", 0xf87171, 0},
};

const CompatTaxonomyEntry kCompatStatusUntested = {@"untested", @"Untested", 0, 0};

const CompatTaxonomyEntry kCompatPerfs[] = {
    {@"great", @"Great", 0x34d399, 0},
    {@"ok", @"Okay", 0x60a5fa, 0},
    {@"poor", @"Poor", 0xfbbf24, 0},
    {@"n/a", @"N/A", 0, 0},
};

UIColor* ColorFromTaxonomy(const CompatTaxonomyEntry& entry) {
  return entry.hex_color ? XEColorFromHexRGB(entry.hex_color) : [XeniaTheme textMuted];
}

const CompatTaxonomyEntry* FindByCode(const CompatTaxonomyEntry* entries, size_t count,
                                      NSString* code) {
  for (size_t i = 0; i < count; ++i) {
    if ([entries[i].code isEqualToString:code]) {
      return &entries[i];
    }
  }
  return nullptr;
}

const CompatTaxonomyEntry* FindCompatStatus(NSString* code) {
  if (const CompatTaxonomyEntry* entry =
          FindByCode(kCompatStatuses, std::size(kCompatStatuses), code)) {
    return entry;
  }
  if ([code isEqualToString:kCompatStatusUntested.code]) {
    return &kCompatStatusUntested;
  }
  return nullptr;
}

const CompatTaxonomyEntry* FindCompatPerf(NSString* code) {
  return FindByCode(kCompatPerfs, std::size(kCompatPerfs), code);
}

}  // namespace

UIColor* xe_compat_status_color(NSString* status) {
  const CompatTaxonomyEntry* entry = FindCompatStatus(status);
  return entry ? ColorFromTaxonomy(*entry) : [XeniaTheme textMuted];
}

NSString* xe_compat_status_label(NSString* status) {
  const CompatTaxonomyEntry* entry = FindCompatStatus(status);
  return entry ? entry->label : @"Unknown";
}

UIColor* xe_compat_perf_color(NSString* perf) {
  const CompatTaxonomyEntry* entry = FindCompatPerf(perf);
  return entry ? ColorFromTaxonomy(*entry) : [XeniaTheme textMuted];
}

NSString* xe_compat_perf_label(NSString* perf) {
  const CompatTaxonomyEntry* entry = FindCompatPerf(perf);
  return entry ? entry->label : @"Unknown";
}

NSString* xe_format_iso_date(NSString* iso) {
  if (!iso || iso.length < 10) {
    return iso ?: @"";
  }
  static NSDateFormatter* parser = nil;
  static NSDateFormatter* date_only_parser = nil;
  static NSDateFormatter* formatter = nil;
  static dispatch_once_t once;
  dispatch_once(&once, ^{
    parser = [[NSDateFormatter alloc] init];
    parser.dateFormat = @"yyyy-MM-dd'T'HH:mm:ss";
    parser.locale = [[[NSLocale alloc] initWithLocaleIdentifier:@"en_US_POSIX"] autorelease];
    date_only_parser = [[NSDateFormatter alloc] init];
    date_only_parser.dateFormat = @"yyyy-MM-dd";
    date_only_parser.locale =
        [[[NSLocale alloc] initWithLocaleIdentifier:@"en_US_POSIX"] autorelease];
    formatter = [[NSDateFormatter alloc] init];
    formatter.dateStyle = NSDateFormatterMediumStyle;
    formatter.timeStyle = NSDateFormatterNoStyle;
  });

  NSString* trimmed = [iso substringToIndex:MIN(iso.length, (NSUInteger)19)];
  NSDate* date = [parser dateFromString:trimmed];
  if (!date) {
    date = [date_only_parser dateFromString:[iso substringToIndex:MIN(iso.length, (NSUInteger)10)]];
  }
  return date ? [formatter stringFromDate:date]
              : [iso substringToIndex:MIN(iso.length, (NSUInteger)10)];
}

NSString* xe_platform_display_text(NSString* platform, NSString* os_version) {
  if (![platform isKindOfClass:[NSString class]] || platform.length == 0) {
    return @"";
  }
  NSString* platform_name = [platform isEqualToString:@"ios"]     ? @"iOS"
                            : [platform isEqualToString:@"macos"] ? @"macOS"
                                                                  : platform;
  if (![os_version isKindOfClass:[NSString class]] || os_version.length == 0) {
    return platform_name;
  }
  return [NSString stringWithFormat:@"%@ %@", platform_name, os_version];
}

NSString* xe_string_from_object(id value) {
  return [value isKindOfClass:[NSString class]] ? (NSString*)value : nil;
}

NSDictionary* xe_dictionary_from_object(id value) {
  return [value isKindOfClass:[NSDictionary class]] ? (NSDictionary*)value : nil;
}

NSInteger xe_compat_status_rank(NSString* status) {
  const CompatTaxonomyEntry* entry = FindCompatStatus(status);
  return entry ? entry->rank : 0;
}

namespace {

const CompatTaxonomyEntry kCompatChannels[] = {
    {@"release", @"Release", 0x34d399, 0},
    {@"preview", @"Preview", 0x60a5fa, 0},
    {@"self-built", @"Self-Built", 0, 0},
};

const CompatTaxonomyEntry kReleaseStages[] = {
    {@"alpha", @"Alpha", 0, 0},
    {@"beta", @"Beta", 0, 0},
    {@"rc", @"RC", 0, 0},
};

